<script lang="ts">import ServiceForm from '$lib/components/workspace/ServiceForm.svelte';let {data,form}=$props();</script><svelte:head><title>服务入口 · 站长工作台</title></svelte:head><main><h1>服务入口</h1><p>仅站长可见；状态为人工记录。本站不探测服务，也不推断链接的实时可用性。</p>{#if form?.error}<p role="alert">{form.error}</p>{/if}{#if form?.success}<p role="status">{form.success}</p>{/if}<ServiceForm value={!form?.input?.id?form?.input:undefined}/>{#each data.services as service}<ServiceForm value={form?.input?.id===service.id?form.input:service} title={service.name}/><p>人工更新于 {new Date(service.status_updated_at).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'})}</p><a href={service.url} rel="noopener noreferrer" target="_blank">打开服务 ↗</a>{/each}</main>
